Slice_unsigned_char lexer__read_identifier(lexer__Lexer* l) {
    {
    int start_pos = (*(l)).position;
    while ((lexer__is_letter((*(l)).ch) || lexer__is_digit((*(l)).ch))) {
    lexer__read_char(l);
    }
    return std_str_slice((*(l)).input, start_pos, (*(l)).position);
    }
}

